on conflict (country_code, calendar_code, calendar_date) do update set
  language_code = excluded.language_code,
  feast_rank = excluded.feast_rank,
  saints = excluded.saints,
  title = excluded.title,
  details = excluded.details,
  fasting_note = excluded.fasting_note,
  editorial_source = excluded.editorial_source,
  is_published = excluded.is_published,
  updated_at = timezone('utc', now());

do $$
declare
  cy_count integer;
  cy_distinct integer;
begin
  select count(*), count(distinct calendar_date)
    into cy_count, cy_distinct
  from public.calendar_days
  where country_code = 'CY'
    and calendar_code = 'cy-church-of-cyprus'
    and calendar_date between date '2026-01-01' and date '2026-12-31';

  if cy_count <> 365 or cy_distinct <> 365 then
    raise exception
      'Expected 365 canonical CY rows for 2026; count=%, distinct=%',
      cy_count, cy_distinct;
  end if;
end
$$;

